$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-17pm-sorted-f1.mjs'
try{[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},8500);try{const v=await(await fetch('http://127.0.0.1:17447/json/version')).json(),w=new WebSocket(v.webSocketDebuggerUrl);await new Promise((ok,no)=>{w.addEventListener('open',ok,{once:true});w.addEventListener('error',no,{once:true})});
let n=0,p=new Map();w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(p.has(z.id)){p.get(z.id)(z);p.delete(z.id)}});
const send=(method,params)=>Promise.race([new Promise(ok=>{const id=++n;p.set(id,ok);w.send(JSON.stringify({id,method,params}))}),new Promise(ok=>setTimeout(()=>ok({error:{message:'cdp_timeout'}}),3500))]);
const z=await send('Target.createTarget',{url:'https://www.avito.ru/krasnoyarsk/telefony?q=iphone%2017%20pro%20max&s=1',background:true,newWindow:false});const target=z.result?.targetId;
const a=target?await send('Target.activateTarget',{targetId:target}):{};
console.log(JSON.stringify({url:'https://www.avito.ru/krasnoyarsk/telefony?q=iphone%2017%20pro%20max&s=1',target_id:target,activated:!!a.result,error:z.error?.message||null}));process.exit(0)
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,100)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
